    catch (error) {
        if (error instanceof DeployApiError &&
            error.status === 404 &&
            error.message === SECRET_NOT_FOUND_MESSAGE) {
            throw new CliError(`No secret named ${name} on deployment ${slug}.`, {
                code: "not_found",
                hint: `Check \`${CLI} secret list ${slug}\` (and the slug / --team).`,
                cause: error,
            });
        }
        throw apiError(error);
    }
    if (ctx.json) {
        ctx.out(`${JSON.stringify({ removed: name }, null, 2)}\n`);
    }
